// === Threads: 3 последних поста ===

// 1) Получаем все входящие объекты
const rows = items.map(i => i.json);

// 2) Вспомогательные функции
const toTime = (v) => {
  if (!v && v !== 0) return 0;
  if (typeof v === 'number' || /^\d+$/.test(String(v))) {
    const n = Number(v);
    return n < 1e12 ? n * 1000 : n; // поддержка секунд/миллисекунд
  }
  const t = Date.parse(String(v));
  return Number.isFinite(t) ? t : 0;
};

const normUsername = (u) => {
  if (!u) return null;
  return String(u).replace(/^@/, '');
};

function buildUrl(r) {
  if (r.URL) return r.URL;
  if (r.url) return r.url;

  const u = normUsername(r.username || r.user?.username || r.owner?.username);
  if (u && r.post_Id) {
    return `https://www.threads.net/@${u}/post/${r.post_Id}`;
  }

  return null;
}

// 3) Нормализация данных
let normalized = rows.map(r => {
  const created = r.createdAt ?? r.updatedAt ?? r.taken_at;
  const ts = toTime(created);
  const url = buildUrl(r);

  const obj = {
    url,
    createdAt: ts ? new Date(ts).toISOString() : undefined,
    _ts: ts,
  };

  Object.keys(obj).forEach(k => (obj[k] == null || obj[k] === '') && delete obj[k]);
  return obj;
});

// 4) Фильтруем только те, у кого есть ссылки и валидная дата
normalized = normalized
  .filter(x => x.url && Number.isFinite(x._ts))
  .sort((a, b) => b._ts - a._ts);

// 5) Берём последние 3
const latest3 = normalized.slice(0, 3).map(({ url, createdAt }) => ({ url, createdAt }));

// 6) Упрощённый массив ссылок
const links = latest3.map(x => x.url);

// 7) Возвращаем в одном объекте
return [{
  json: {
    total: rows.length,
    latest3,
    links
  }
}];

// === Threads: Формирование ответа для ИИ агента ===

// 1) Получаем данные из предыдущей ноды
const inputData = $input.all()[0].json;

// 2) Извлекаем username, если он есть (необязательно, но удобно)
const username = inputData.username || inputData.profile?.username || "Неизвестный пользователь";

// 3) Извлекаем ссылки из latest3
const threadLinks = inputData.latest3.map(post => post.url);

// 4) Формируем результирующий объект
const result = {
  message: `Анализ контента Threads пользователя ${username} выполнен успешно`,
  username: username,
  top_threads: {
    description: "3 последних поста пользователя",
    links: threadLinks
  }
};

// 5) Возвращаем результат
return result;

